{"policy":"permit (
    principal is User,
    action == Action::"approveInvoice",
    resource is Invoice
)
when {
    (principal.roles.contains(Role::"approver") ||
     principal.roles.contains(Role::"financeManager")) &&
    resource.status == InvoiceStatus::"submitted"
};

forbid (
    principal is User,
    action == Action::"approveInvoice",
    resource is Invoice
)
when {
    resource.status != InvoiceStatus::"submitted"
};

permit (
    principal is User,
    action == Action::"issuePayment",
    resource is Payment
)
when {
    principal.roles.contains(Role::"financeManager") &&
    resource.invoice.status == InvoiceStatus::"approved" &&
    resource.invoice has approver
};

forbid (
    principal is User,
    action == Action::"issuePayment",
    resource is Payment
)
when {
    resource.invoice has approver &&
    resource.invoice.approver == principal &&
    !context.emergencyDeclared
};"}
